SELECT id, creator_id FROM note

    
        AND id > #{cursor}
    
    
        AND topic_id IN
        
            #{topicId}
        
    
    
        AND creator_id = #{loginUserId}
    
    
        AND visible = 0
    
        AND status = 1

ORDER BY id asc
LIMIT #{limit}

SELECT id, title, img_uris, video_uri, create_time, is_top, type, status, review_reason
FROM note
WHERE creator_id = #{creatorId}
AND is_top = 0
AND status != 2

    AND status = #{status}


    AND id < #{cursor}

ORDER BY id DESC
LIMIT #{limit}

SELECT id, title, img_uris, video_uri, create_time, is_top, type, status, review_reason FROM note WHERE creator_id = #{creatorId} AND is_top = 1 AND status != 2
AND status = #{status}
ORDER BY id DESC

SELECT id, title, img_uris, video_uri, create_time, update_time, is_top, type, status, visible,
       creator_id, topic_id, topic_name, review_method, review_reason, reviewed_at, review_version
FROM note

    
        AND status = #{status}
    
    
        AND creator_id = #{creatorId}
    
    
        AND id < #{cursor}
    

ORDER BY id DESC
LIMIT #{limit}

SELECT creator_id AS userId,
       COUNT(*) AS count
FROM note
WHERE create_time >= #{startTime}
  AND create_time < #{endTime}
  AND status != #{deletedStatus}
GROUP BY creator_id
ORDER BY count DESC, creator_id DESC
LIMIT #{limit}

SELECT c.name AS name,
       COUNT(DISTINCT n.id) AS count
FROM note n
INNER JOIN channel_topic_rel ctr ON ctr.topic_id = n.topic_id
INNER JOIN channel c ON c.id = ctr.channel_id AND c.is_deleted = 0
WHERE n.create_time >= #{startTime}
  AND n.create_time < #{endTime}
  AND n.status != #{deletedStatus}
GROUP BY c.id, c.name
ORDER BY count DESC, c.id ASC
